using System;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class ApplicationsPage:UserControl{DataGridView grid;ComboBox stage;NumericUpDown score;public ApplicationsPage(){BackColor=Theme.Background;var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=58,Padding=new Padding(0,6,0,6)};stage=new ComboBox{Width=150,DropDownStyle=ComboBoxStyle.DropDownList};stage.Items.AddRange(new object[]{"Applied","Screening","Interview","Offer","Hired","Rejected"});stage.SelectedIndex=0;score=new NumericUpDown{Minimum=0,Maximum=100,Width=70};var update=Ui.Button(L.Fa?"بروزرسانی مرحله":"Update stage");update.Enabled=AppSession.Can("Applications.Manage");update.Click+=(s,e)=>UpdateStage();bar.Controls.Add(stage);bar.Controls.Add(score);bar.Controls.Add(update);Controls.Add(bar);grid=Ui.Grid();Controls.Add(grid);grid.BringToFront();LoadData();}void LoadData(){grid.DataSource=Database.Query("SELECT a.Id,j.Title AS Job,c.FullName AS Candidate,a.Stage,a.Score,a.AppliedAt FROM Applications a JOIN Jobs j ON j.Id=a.JobId JOIN Candidates c ON c.Id=a.CandidateId ORDER BY CASE a.Stage WHEN 'Offer' THEN 1 WHEN 'Interview' THEN 2 WHEN 'Screening' THEN 3 WHEN 'Applied' THEN 4 ELSE 5 END,a.Id DESC");}void UpdateStage(){if(grid.CurrentRow==null)return;var id=Convert.ToInt32(grid.CurrentRow.Cells["Id"].Value);Database.Exec("UPDATE Applications SET Stage=@s,Score=@sc WHERE Id=@id",new SqlParameter("@s",stage.Text),new SqlParameter("@sc",(int)score.Value),new SqlParameter("@id",id));Database.Exec("INSERT Notifications(UserId,Title,Message) VALUES(NULL,@t,@m)",new SqlParameter("@t",L.Fa?"تغییر وضعیت درخواست":"Application updated"),new SqlParameter("@m",grid.CurrentRow.Cells["Candidate"].Value+" → "+stage.Text));Database.Audit("StageChange","Application",id+" -> "+stage.Text);LoadData();}}}